tools.example:
update_compile_order -fileset sources_1
foreach f [get_files -compile_order sources -used_in synthesis] { puts $f }
puts [get_files -of_objects [get_filesets constrs_1]]
foreach f [get_files -filter {FILE_TYPE == "VHDL"}] {
    set_property file_type {VHDL 2008} $f
}

foreach fs [get_filesets] {
    puts [format "%-16s %s" $fs [get_property FILESET_TYPE $fs]]
}
set_property top fir_top [get_filesets sources_1]
set_property top tb_fir  [get_filesets sim_1]
puts [get_files -of_objects [get_filesets sim_1]]

foreach r [get_runs] {
    puts [format "%-18s %-6s %s" $r [get_property PROGRESS $r] [get_property STATUS $r]]
}

# Relaunch everything that has gone stale
set stale [get_runs -filter {NEEDS_REFRESH}]
foreach r $stale { reset_run $r }
if {[llength $stale]} {
    launch_runs $stale -jobs 8
    foreach r $stale { wait_on_run $r }
}

foreach r [get_runs impl_explore_*] {
    puts "Deleting $r"
    delete_runs $r
}
delete_runs -noclean_dir [get_runs synth_perf]
puts [get_runs]
